package com.fintrack.khmtomnenh.product.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.product.dto.ProductDto; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.product.service.ProductService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") @RequiredArgsConstructor public class ProductController {private final ProductService s;@GetMapping public List<Product> list(){return s.list();}@GetMapping("/{id}") public Product get(@PathVariable Long id){return s.get(id);}@PostMapping @PreAuthorize("hasRole('SUPPLIER')") public ResponseEntity<Product> create(@Valid @RequestBody ProductDto d,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(d,a));}@PutMapping("/{id}") @PreAuthorize("hasRole('SUPPLIER')") public Product update(@PathVariable Long id,@Valid @RequestBody ProductDto d,@AuthenticationPrincipal Auth a){return s.update(id,d,a);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('SUPPLIER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal Auth a){s.delete(id,a);}}
